VI = {
"0.1": ("Mục lục", "Hành trình của chúng ta có mười bảy chặng: từ những tảng đá rơi từ vũ trụ đến đáy đại dương sâu nhất, từ những cơn gió dữ dội nhất đến những sa mạc khô cằn nhất."),
# 1
"1.1": ("Trái Đất nhìn từ vũ trụ", "Nhìn từ xa, Trái Đất có vẻ thật yên bình: một viên bi xanh trắng lặng lẽ xoay trong bóng tối. Nhưng nhìn gần, hành tinh của chúng ta chưa bao giờ đứng yên. Suốt 4,6 tỷ năm, nó không ngừng sôi sục, đóng băng và tự định hình lại. Chào mừng bạn đến với những kỳ quan của Trái Đất."),
"1.2": ("Thiên thạch thành sao băng", "Mỗi ngày, những mẩu đá và kim loại từ vũ trụ lao vào bầu khí quyển. Ma sát khiến chúng nóng rực lên, và ta thấy chúng là sao băng, hay những quả cầu lửa chói lòa."),
"1.3": ("Mưa sao băng năm 1833", "Tháng 11 năm 1833, trận mưa sao băng rực rỡ nhất từng được ghi nhận đã thắp sáng bầu trời nước Mỹ. Nhiều người choàng tỉnh và tin rằng tận thế đã đến."),
"1.4": ("Cú va chạm Chicxulub", "Khoảng 66 triệu năm trước, một khối đá khổng lồ từ vũ trụ đâm xuống gần Chicxulub, ở Mexico ngày nay. Bụi của nó che khuất ánh mặt trời, và phần lớn các loài động vật, kể cả khủng long, đã bị tuyệt chủng."),
"1.5": ("Sức mạnh va chạm và hố Vredefort", "Một cú va chạm như thế có thể nung nóng không khí tới khoảng 60.000 độ C, nóng gấp mười lần bề mặt Mặt Trời. Vết sẹo lớn nhất được biết đến, hố Vredefort ở Nam Phi, rộng khoảng 300 ki-lô-mét."),
"1.6": ("Cực quang và gió Mặt Trời", "Có những vị khách thật đẹp. Các hạt bị gió Mặt Trời thổi đến va vào từ trường Trái Đất, thắp sáng bầu trời vùng cực bằng những dải cực quang xanh lục và tím."),
"1.7": ("Sao chổi Hyakutake", "Sao chổi là những khối băng và đá rực sáng khi tiến gần Mặt Trời. Năm 1996, sao chổi Hyakutake bay sát Trái Đất, và phải hàng chục nghìn năm nữa nó mới quay trở lại."),
# 2
"2.1": ("Lõi nóng như phòng máy", "Muốn hiểu vì sao hành tinh rung chuyển, hãy đi đến tận trái tim của nó. Lõi Trái Đất nóng khoảng 5.400 độ C, ngang bề mặt Mặt Trời, và sức nóng ấy khiến lớp đá bên trên không ngừng chuyển động."),
"2.2": ("Các lớp của Trái Đất", "Trái Đất được cấu tạo thành nhiều lớp: lõi trong bằng sắt rắn, lõi ngoài lỏng, lớp manti chảy rất chậm, và lớp vỏ mỏng nơi chúng ta sống. Khi manti cuộn chảy, lớp vỏ bị nứt vỡ."),
"2.3": ("Các mảng kiến tạo", "Những vết nứt ấy chia bề mặt thành các mảng kiến tạo khổng lồ. Chúng trôi đi vài xăng-ti-mét mỗi năm, và ở nơi chúng gặp nhau hay tách xa nhau, Trái Đất trở nên dữ dội."),
"2.4": ("Vành đai lửa Thái Bình Dương", "Quanh Thái Bình Dương là Vành đai lửa, một vòng cung hình móng ngựa gồm các ranh giới mảng, nơi tập trung hơn 75 phần trăm số núi lửa trên thế giới và những trận động đất dữ dội nhất."),
"2.5": ("Sống núi giữa Đại Tây Dương", "Dưới lòng Đại Tây Dương là sống núi giữa đại dương, dài khoảng 16.000 ki-lô-mét. Tại đây, dung nham trào lên qua khe nứt, đáy biển mới hình thành, và đại dương rộng thêm một chút mỗi năm."),
"2.6": ("Iceland, xứ sở của lửa và băng", "Ở Iceland, dãy núi ngầm ấy nhô lên khỏi mặt nước. Hòn đảo của lửa và băng này đang dần bị kéo tách ra, giữa Bắc Mỹ và châu Âu."),
"2.7": ("Đám mây tro Eyjafjallajökull", "Năm 2010, núi lửa Eyjafjallajökull của Iceland phun tro bụi cao 11 ki-lô-mét. Đám mây trôi qua châu Âu, và suốt khoảng một tuần, giao thông hàng không gần như tê liệt."),
# 3
"3.1": ("Sự ra đời của dãy Himalaya", "Khi Ấn Độ va vào châu Á, cú va chạm đã đẩy dãy Himalaya trồi lên, và đến nay nó vẫn tiếp tục cao thêm. Trên đỉnh của nó là ngọn núi cao nhất Trái Đất: Chomolungma, Sagarmatha, hay núi Everest."),
"3.2": ("Đo đạc đỉnh núi", "Vào thế kỷ 19, các nhà khảo sát người Anh ở Ấn Độ phát hiện một đỉnh núi xa xôi cao hơn mọi ngọn núi từng được đo. Năm 1865, nó được đặt theo tên ngài George Everest."),
"3.3": ("Đo Everest ngày nay", "Chiều cao chính xác của nó vẫn còn tranh cãi, vì tuyết, băng và phương pháp đo đều làm thay đổi kết quả. Năm 2020, Trung Quốc và Nepal thống nhất con số 8.848,86 mét."),
"3.4": ("Lên đỉnh lần đầu, 1953", "Ngày 29 tháng 5 năm 1953, Edmund Hillary và Tenzing Norgay trở thành những người đầu tiên đứng trên nóc nhà thế giới. Từ đó, hàng nghìn người đã nối bước họ."),
"3.5": ("Trại chính và thác băng Khumbu", "Người leo núi ở lại nhiều tuần tại Trại chính, độ cao 5.400 mét, để cơ thể quen với không khí loãng. Phía trên là thác băng Khumbu chết chóc, phải vượt qua bằng dây thừng và thang nhôm."),
"3.6": ("Hành trình qua các trại", "Sau đó họ leo qua một chuỗi trại, từ 6.000 đến 8.000 mét, vượt qua mỏm Geneva, bên cạnh hai người hàng xóm khổng lồ là Lhotse và Nuptse."),
"3.7": ("Vùng tử thần", "Trên 8.000 mét là Vùng tử thần. Mỗi hơi thở chỉ chứa một phần ba lượng ô-xy so với mực nước biển, và người leo núi phải bám vào băng bằng rìu và đinh giày."),
"3.8": ("Rác thải và năm đỉnh núi cao nhất", "Đáng buồn là Everest cũng là bãi rác cao nhất thế giới. Và nó không đơn độc: K2, Kangchenjunga, Lhotse và Makalu cùng Everest là năm đỉnh núi cao nhất Trái Đất."),
# 4
"4.1": ("Phun trào và thang đo", "Khi mặt đất nứt toác, đá nóng chảy, tro bụi và khí độc phun trào. Các nhà khoa học xếp hạng các vụ phun trào theo một thang đo, từ nhẹ nhàng cho đến siêu khủng khiếp."),
"4.2": ("Cấu tạo núi lửa", "Bên trong núi lửa, mác-ma tích tụ trong những khoang sâu. Nhiệt và áp suất đẩy nó lên qua ống dẫn trung tâm tới miệng núi, hoặc thoát ra hai bên qua các khe nứt ở sườn núi."),
"4.3": ("Núi St. Helens, 1980", "Năm 1980, núi St. Helens phát nổ dữ dội đến mức toàn bộ sườn bắc sụp đổ, và ngọn núi thấp đi khoảng 400 mét chỉ trong một ngày."),
"4.4": ("Dung nham chảy ra biển", "Dung nham có thể chảy rất nhanh. Ở núi lửa Nyiragongo, Congo, nó lao đi với tốc độ hơn 60 ki-lô-mét một giờ. Và khi dung nham gặp đại dương, nước biển sôi lên thành hơi."),
"4.5": ("Hồ Taupo", "Gần hai nghìn năm trước, một ngọn núi lửa ở New Zealand đã phun ra khoảng 100 ki-lô-mét khối đá. Miệng núi lửa khổng lồ của nó nay là hồ Taupo."),
"4.6": ("Vesuvius và Pompeii, năm 79", "Năm 79, núi Vesuvius phun cột tro cao 33 ki-lô-mét. Khi cột tro đổ sập, nó chôn vùi thành phố La Mã Pompeii."),
"4.7": ("Miệng núi lửa Hawaii", "Từng lớp dung nham và tro bụi chồng lên nhau tạo nên hình nón của núi lửa. Ở Hawaii, các miệng núi lửa còn hoạt động phả hơi nước gần như mỗi ngày, từ từ tạo nên vùng đất mới."),
# 5
"5.1": ("Sức nóng trồi lên mặt đất", "Ở một số nơi, sức nóng của Trái Đất trồi lên tận mặt đất. Nước ngầm bị đun nóng quá điểm sôi và phụt ra thành những cột hơi bỏng rát, đến cả bùn cũng sủi bọt."),
"5.2": ("Mạch phun Old Faithful", "Mạch phun Old Faithful ở Yellowstone phun nước cao tới 55 mét, khoảng một tiếng rưỡi một lần: đó là thời gian khoang nước bên dưới cần để đầy và nóng trở lại."),
"5.3": ("Yellowstone và hõm chảo núi lửa", "Yellowstone có khoảng một nửa số mạch phun nước nóng của thế giới, cùng hàng nghìn suối nước nóng. Và tất cả nằm bên trong hõm chảo của một siêu núi lửa."),
"5.4": ("Siêu núi lửa và núi lửa thường", "Núi lửa thường tạo nên núi. Siêu núi lửa thì thổi tung chúng. Lần phun trào lớn gần nhất của Yellowstone mạnh gấp khoảng một nghìn lần vụ St. Helens."),
"5.5": ("Mạch phun Waimangu", "Ở New Zealand, mạch phun Waimangu chỉ hoạt động trong bốn năm, từ năm 1900. Những cột nước của nó cao tới 460 mét, cao hơn cả tòa nhà Empire State."),
"5.6": ("Khỉ tuyết tắm suối nóng", "Ở Nagano, Nhật Bản, những chú khỉ tuyết ngâm mình trong suối nước nóng suốt mùa đông giá rét. Có con thoải mái đến mức ngủ gật ngay trong nước."),
"5.7": ("Pamukkale, Lâu đài bông", "Ở Pamukkale, Thổ Nhĩ Kỳ, dòng nước nóng giàu khoáng chất đã tạo nên những bậc thềm đá trắng lấp lánh. Cái tên của nó có nghĩa là Lâu đài bông."),
# 6
"6.1": ("Đá dưới áp lực", "Đá rất cứng, nhưng cũng giòn. Khi bị ép quá giới hạn, lớp vỏ Trái Đất oằn lại và trượt đi, khiến mặt đất rung chuyển và vỡ nát."),
"6.2": ("Đứt gãy hoạt động thế nào", "Điều đó xảy ra dọc theo các đứt gãy, nơi những khối đá cọ xát vào nhau. Chúng bị kẹt lại, áp lực tích tụ, rồi đột ngột bật mạnh về phía trước: đó là động đất."),
"6.3": ("Chấn tiêu, chấn tâm và sóng địa chấn", "Nơi đá vỡ dưới lòng đất gọi là chấn tiêu. Điểm ngay phía trên mặt đất là chấn tâm. Từ đó, sóng địa chấn lan ra mọi hướng, làm rung chuyển các thị trấn và thành phố."),
"6.4": ("Đứt gãy San Andreas và Concepción", "Năm 1906, đứt gãy San Andreas xé toạc San Francisco. Năm 2010, một trận động đất ở Chile đã dịch chuyển cả thành phố Concepción khoảng ba mét về phía tây."),
"6.5": ("Thị trấn miền núi đổ nát", "Năm 2008, một trận động đất cực mạnh tấn công Tứ Xuyên, Trung Quốc. Đường sá nứt toác, sườn đồi sạt lở, và cả những thị trấn bị san thành đống đổ nát."),
"6.6": ("Nhà chống động đất", "Động đất vẫn chưa thể dự báo, nhưng con người có thể xây dựng thông minh hơn. Ở Nhật Bản và California, những tòa nhà linh hoạt trên móng giảm chấn có thể lắc lư thay vì sụp đổ."),
"6.7": ("Sóng thần hình thành", "Khi một đứt gãy trượt dưới đáy biển, nó có thể tạo ra sóng thần. Năm 2004, những con sóng khổng lồ quét qua Ấn Độ Dương, từ Indonesia đến Thái Lan."),
# 7
"7.1": ("Sức mạnh của những dòng sông", "Sông có thể nghiền đá thành bụi và cung cấp năng lượng cho cả những thành phố. Và xét theo hầu hết mọi tiêu chí, có một dòng sông vượt trội tất cả: sông Amazon."),
"7.2": ("Đầu nguồn ở dãy Andes", "Nó bắt đầu từ trên cao dãy Andes, nơi nước băng tan chảy xuống, và những dòng suối như sông Urubamba hợp lại thành đầu nguồn."),
"7.3": ("Hơn một nghìn phụ lưu", "Trên khắp Nam Mỹ, hơn 1.100 phụ lưu đổ vào Amazon, nhiều hơn bất kỳ dòng sông nào khác, có những nhánh đổ về như những thác nước ầm ầm."),
"7.4": ("Amazon và sông Nin", "Sông Nin có thể dài hơn một chút, nhưng mỗi giây, Amazon đổ ra biển lượng nước gấp khoảng 43 lần. Không dòng sông nào sánh kịp."),
"7.5": ("Lưu vực và cửa sông Amazon", "Vào mùa mưa, nước lũ của nó lan rộng trên một diện tích bằng cả nước Đức, nuôi dưỡng khu rừng nhiệt đới lớn nhất Trái Đất."),
"7.6": ("Vùng ngập lũ và cá heo sông", "Những cánh rừng ngập nước trải dọc bờ sông, và trong những kênh nước đục ngầu ấy là một trong những loài vật bí ẩn nhất của nó: cá heo sông."),
"7.7": ("Phù sa và sóng pororoca", "Nơi sông gặp biển, thủy triều đẩy ngược lại. Một con sóng dài gọi là pororoca cuộn ngược dòng, và người lướt sóng có thể cưỡi nó tới mười ki-lô-mét."),
# 8
"8.1": ("Cảnh quan luôn biến đổi", "Trên hành tinh không ngừng chuyển động này, cảnh quan luôn bị chạm khắc và định hình lại, chậm đến mức một đời người không thể nhận ra. Nhưng kết quả thì ở khắp quanh ta."),
"8.2": ("Gió mài đá ở Arches", "Ở những nơi khô hạn, gió trở thành nhà điêu khắc, dùng cát mài mòn đá. Ở Vườn quốc gia Arches, bang Utah, gió đã tạc nên những vòm đá tự nhiên và những tảng đá chênh vênh."),
"8.3": ("Cột đá hoodoo và Devils Marbles", "Gió để lại những hình thù kỳ lạ: cột đá hoodoo cao vút đội mũ đá cứng, và ở Úc là Devils Marbles, những tảng đá tròn khổng lồ chồng lên nhau."),
"8.4": ("Hẻm núi khe", "Dòng nước xiết có thể cắt một khe sâu và hẹp xuyên qua đá mềm: đó là hẻm núi khe, rực sáng nhờ ánh sáng rọi xuống từ trên cao."),
"8.5": ("Grand Canyon", "Nhà điêu khắc vĩ đại nhất là sông Colorado. Qua hàng triệu năm, nó đã khoét nên Grand Canyon, dài 446 ki-lô-mét và sâu hơn 1,6 ki-lô-mét."),
"8.6": ("Xói mòn bờ biển", "Ở bờ biển, những con sóng mang theo cát mài mòn vách đá, cho đến khi phần đá phía trên bị khoét chân và đổ sập xuống biển."),
# 9
"9.1": ("Từ tuyết thành sông băng", "Ở nơi tuyết hiếm khi tan, tuyết chồng chất và bị nén thành băng rắn. Dưới sức hút của trọng lực, khối băng ấy chậm rãi trườn xuống dốc, trở thành sông băng."),
"9.2": ("Sông băng Perito Moreno vỡ", "Ở mặt trước sông băng, băng vỡ ra với tiếng nứt như sấm. Ở Argentina, những tháp băng đổ ầm từ sông băng Perito Moreno xuống mặt hồ bên dưới."),
"9.3": ("Tiến và lùi: sông băng Hubbard", "Khi băng hình thành nhiều hơn tan, sông băng tiến lên. Khi tan nhiều hơn, nó lùi lại. Sông băng Hubbard ở Alaska đã tiến lên suốt hơn một thế kỷ."),
"9.4": ("Jakobshavn, sông băng tốc độ", "Hầu hết sông băng chỉ di chuyển nhiều nhất vài mét mỗi ngày. Nhưng sông băng Jakobshavn ở Greenland trôi tới 20 mét mỗi ngày."),
"9.5": ("Núi băng trôi và tàu Titanic", "Những mảng vỡ ra trở thành núi băng trôi, với khoảng 90 phần trăm ẩn dưới mặt nước. Năm 1912, một núi băng đã đánh chìm tàu Titanic, khiến hơn 1.500 người thiệt mạng."),
"9.6": ("Chim cánh cụt trên băng trôi", "Nhưng với chim cánh cụt ở Nam Đại Dương, núi băng trôi lại là chiếc bè tiện lợi để nghỉ ngơi, trước khi lặn xuống bắt cá."),
"9.7": ("Kỷ băng hà và Kilimanjaro", "Trong kỷ băng hà gần nhất, mực nước biển hạ xuống khoảng 120 mét, và voi ma mút lang thang trên những đồng cỏ lạnh giá. Ngày nay, chỏm băng trên núi Kilimanjaro đang tan rất nhanh."),
# 10
"10.1": ("Thế giới dưới lòng đất", "Dưới chân chúng ta là một thế giới ẩn giấu với những hang động tối tăm và đường hầm quanh co, nơi cất giữ những cảnh tượng kỳ vĩ bậc nhất hành tinh."),
"10.2": ("Đá vôi từ sinh vật biển cổ", "Hầu hết hang động được khoét trong đá vôi, vốn hình thành từ vỏ của những sinh vật biển cổ đại, bị nén từng lớp thành đá suốt hàng triệu năm."),
"10.3": ("Hang động và thạch nhũ", "Nước mưa có tính a-xít nhẹ hòa tan đá vôi thành những đường hầm. Rồi những giọt nước nhỏ xuống tạo nên thạch nhũ rủ từ trần và măng đá mọc lên từ nền."),
"10.4": ("Hố sụt", "Đôi khi mặt đất phía trên hang sụp xuống. Ở Guatemala, một hố sụt sâu khoảng 30 tầng nhà đã bất ngờ nuốt chửng một tòa nhà ba tầng."),
"10.5": ("Nhà thám hiểm hang động", "Những nhà thám hiểm hang động yêu điều chưa biết. Nhưng họ phải đối mặt với đá rơi, nước lạnh cóng, lũ bất ngờ, và nguy cơ lạc lối trong bóng tối."),
"10.6": ("Hang khổng lồ: Mulu và Sơn Đoòng", "Ở Borneo, khoang hang Sarawak là khoang hang lớn nhất từng được biết đến. Còn ở Việt Nam, hang Sơn Đoòng rộng lớn đến mức có cả rừng và mây riêng."),
"10.7": ("Hang Mammoth, hang dài nhất", "Hệ thống hang dài nhất Trái Đất là hang Mammoth ở bang Kentucky. Hơn 686 ki-lô-mét đã được lập bản đồ, và các nhà thám hiểm vẫn đang tìm thêm."),
# 11
"11.1": ("Rương báu trong lòng đất", "Vỏ Trái Đất là một chiếc rương báu. Nhiều thứ ta dùng hằng ngày, từ phấn rôm đến ruột bút chì, đều được hình thành sâu bên trong nó."),
"11.2": ("Vật liệu xây dựng", "Nhà cửa của chúng ta được làm từ đó: đá cẩm thạch cho những công trình vĩ đại, thép từ sắt, nhôm nhẹ, và thạch cao để làm vữa trát tường và phấn viết bảng."),
"11.3": ("Đồng, niken và thủy ngân", "Máy móc của chúng ta vận hành nhờ nó. Đồng dẫn điện, niken dùng trong pin, và thủy ngân lỏng từng nằm trong nhiệt kế."),
"11.4": ("Coltan và điện thoại di động", "Ngay cả chiếc điện thoại của bạn cũng cần một khoáng chất gọi là coltan, thường được đào bằng tay ở Congo, trong những hầm mỏ nguy hiểm và cảnh nghèo đói cùng cực."),
"11.5": ("Fluorit, hematit và vàng", "Có những khoáng chất thật đẹp. Fluorit phát sáng dưới tia cực tím, hematit từng là màu đỏ trong tranh đá cổ, và một gam vàng có thể dát mỏng phủ kín một mét vuông."),
"11.6": ("Kim cương và than chì", "Kim cương và than chì trong bút chì đều là các-bon tinh khiết, chỉ khác cách sắp xếp. Vương miện Hoàng gia Ấn Độ được nạm hơn 6.000 viên kim cương."),
"11.7": ("Giàn khoan Deepwater Horizon", "Khai thác kho báu rất nguy hiểm. Năm 2010, giàn khoan Deepwater Horizon phát nổ ở vịnh Mexico, gây ra vụ tràn dầu do tai nạn lớn nhất lịch sử."),
# 12
"12.1": ("Biển sâu bí ẩn", "Biển sâu là nơi ít được khám phá nhất Trái Đất: tối tăm, lạnh giá và áp suất khủng khiếp. Vậy mà sự sống vẫn sinh sôi, từ mực khổng lồ đến những loài cá tự phát sáng."),
"12.2": ("Các tầng đại dương", "Càng lặn sâu, ánh sáng càng mờ dần: tầng có ánh nắng, tầng chạng vạng, tầng tối, tầng vực thẳm, và sâu nhất là những rãnh đại dương."),
"12.3": ("Tuyết biển", "Trong bóng tối, tuyết rơi. Những mảnh vụn nhỏ của thực vật và động vật chết trôi xuống thành tuyết biển, tạo nên những lớp bùn dày dưới đáy."),
"12.4": ("Bạch tuộc Dumbo và ostracod khổng lồ", "Sinh vật nơi đây trông như đến từ hành tinh khác. Bạch tuộc Dumbo vẫy đôi vây như tai voi, còn ostracod khổng lồ lướt trong bóng tối như những chiếc đèn lồng."),
"12.5": ("Miệng phun khói đen", "Dưới đáy biển, những miệng phun khói đen phun ra dòng nước nóng tới 400 độ C, và tôm mù cùng giun ống tụ tập quanh đó như một ốc đảo."),
"12.6": ("Tàu lặn Trieste, 1960", "Năm 1960, Jacques Piccard và Don Walsh ngồi trong tàu lặn Trieste xuống sâu gần 11 ki-lô-mét, tới vực Challenger trong rãnh Mariana."),
"12.7": ("Đáy biển sâu nhất và Mặt Trăng", "Đến năm 2022, mới chỉ có 27 người chạm tới điểm sâu nhất ấy, chỉ nhiều hơn một chút so với 12 người từng đặt chân lên Mặt Trăng."),
"12.8": ("Robot lập bản đồ đáy biển", "Ngày nay, robot đảm nhận phần lớn việc lặn sâu, dùng sóng âm để vẽ bản đồ những dãy núi và thung lũng dưới nước mà chưa mắt người nào từng thấy."),
# 13
"13.1": ("Vô hình nhưng hủy diệt", "Gió chỉ là không khí chuyển động, vô hình và gần như không có trọng lượng. Thế nhưng nó là một trong những lực hủy diệt mạnh nhất hành tinh."),
"13.2": ("Vì sao không khí chuyển động", "Mặt Trời làm nóng Trái Đất không đều. Không khí ấm bốc lên, không khí lạnh tràn vào, và những dòng chảy bất tận ấy tạo nên thời tiết, đôi khi là thời tiết cực đoan."),
"13.3": ("Từ bão siêu tế bào đến lốc xoáy", "Khi không khí nóng ẩm gặp không khí lạnh khô, một cơn bão xoáy khổng lồ gọi là siêu tế bào có thể hình thành. Từ chân mây, một cơn lốc xoáy vươn xuống mặt đất."),
"13.4": ("Đợt lốc xoáy năm 1974", "Ngày 3 tháng 4 năm 1974, gần 150 cơn lốc xoáy càn quét nước Mỹ trong chưa đầy một ngày, khiến khoảng 300 người thiệt mạng."),
"13.5": ("Ba tên gọi của bão lớn", "Những cơn bão lớn nhất có ba tên gọi: hurricane, typhoon và cyclone. Sức gió của chúng vượt 250 ki-lô-mét một giờ, đẩy những đợt nước dâng chết người vào đất liền."),
"13.6": ("Galveston 1900 và Katrina 2005", "Năm 1900, một cơn bão nhấn chìm thành phố Galveston, bang Texas, khiến tới 10.000 người thiệt mạng. Năm 2005, bão Katrina tàn phá New Orleans."),
"13.7": ("Thợ săn bão", "Ở Hành lang lốc xoáy của nước Mỹ, những thợ săn bão lao về phía cơn bão để thu thập dữ liệu. Có người còn lái xe bọc thép vào tận tâm lốc xoáy."),
# 14
"14.1": ("Từ thần thoại đến khoa học", "Hàng thế kỷ, thời tiết kỳ lạ bị coi là cơn thịnh nộ của thần linh. Ngày nay, các nhà khoa học biết rằng hầu hết những hiện tượng ấy đều có nguyên nhân tự nhiên."),
"14.2": ("Những đám mây kỳ lạ", "Hãy nhìn những đám mây. Chúng có thể mang hình nấm, hình sứa, thậm chí hình bánh vòng. Còn mây vú, treo lủng lẳng như những chiếc túi, báo hiệu bão sắp đến."),
"14.3": ("Vòi rồng và mưa cá", "Cá thật sự có thể rơi từ trên trời. Vòi rồng trên mặt nước hút động vật lên khỏi sông hồ, rồi thả chúng xuống cách đó nhiều ki-lô-mét theo cơn mưa."),
"14.4": ("Quầng Mặt Trời và mặt trời giả", "Những tinh thể băng trên các đám mây mỏng có thể bao quanh Mặt Trời bằng một quầng sáng, kèm những đốm sáng rực hai bên gọi là mặt trời giả."),
"14.5": ("Mưa đá kỷ lục", "Mưa đá có thể rất lớn. Năm 2010, một viên mưa đá rộng khoảng 20 xăng-ti-mét đã rơi xuống Vivian, bang Nam Dakota."),
"14.6": ("Sét, sét núi lửa và sét hòn", "Sét đánh khoảng 100 lần mỗi giây, kể cả bên trong đám mây tro núi lửa. Còn sét hòn phát sáng vẫn là một bí ẩn."),
"14.7": ("Sét sprite, tia xanh và trăng xanh", "Phía trên những cơn giông, sét đỏ sprite và tia xanh chớp nháy. Và khi khói hay tro bụi phủ kín bầu trời, cả Mặt Trăng cũng có thể ngả màu xanh."),
"14.8": ("Lũ quét", "Lũ quét ập đến gần như không báo trước. Năm 2010 và 2011, lũ lụt ở Queensland, Úc, bao phủ một diện tích lớn hơn cả Pháp và Đức cộng lại."),
# 15
"15.1": ("Tuyết đẹp nhưng nguy hiểm", "Tuyết có thể biến cảnh vật thành xứ sở thần tiên trắng xóa. Nhưng ở dạng khắc nghiệt nhất, từ bão tuyết đến tuyết lở, nó trở thành sát thủ."),
"15.2": ("Bông tuyết lớn lên thế nào", "Bông tuyết bắt đầu là những tinh thể băng sáu cạnh nhỏ xíu, rồi mọc nhánh thành những hình dạng phức tạp, tùy theo nhiệt độ và độ ẩm của không khí."),
"15.3": ("Mỗi bông tuyết là duy nhất", "Có phải mỗi bông tuyết là duy nhất? Gần như chắc chắn. Với hàng nghìn tỷ bông rơi mỗi năm, hai bông giống hệt nhau gần như là điều không thể."),
"15.4": ("Kỷ lục tuyết ở núi Baker", "Mùa đông năm 1998 sang 1999, núi Baker ở bang Washington ghi nhận lượng tuyết 29 mét, cao bằng một tòa nhà mười tầng."),
"15.5": ("Bão tuyết và mù trắng", "Khi gió mạnh thổi tuyết dày, bão tuyết có thể biến thành mù trắng, dày đặc đến mức bạn không nhìn thấy bàn tay mình."),
"15.6": ("Tuyết lở vùng Alps", "Năm 1999, gần Chamonix, nước Pháp, một trận tuyết lở lao xuống với tốc độ gần 100 ki-lô-mét một giờ và chôn vùi một ngôi làng."),
"15.7": ("Sống sót khi tuyết lở", "Đội cứu hộ khuyên: mang theo máy định vị, di chuyển sang bên, bám vào cây, bơi để giữ mình trên mặt tuyết, tạo khoảng trống để thở, và đánh dấu nơi người khác biến mất."),
# 16
"16.1": ("Mặt trời nửa đêm và đêm vùng cực", "Ở Bắc Cực, Mặt Trời mùa hè không bao giờ lặn. Và vào mùa đông, có những ngày Mặt Trời không hề mọc."),
"16.2": ("Tàu ngầm dưới Bắc Cực", "Năm 1958, một tàu ngầm đi ngang bên dưới Bắc Cực và chứng minh nơi đó không có đất liền, chỉ có băng trôi."),
"16.3": ("Động vật Bắc Cực", "Gấu Bắc Cực săn hải cẩu trên băng, cáo Bắc Cực bám theo để nhặt phần thừa, và dưới lớp băng, thợ lặn tìm thấy sự sống đáng kinh ngạc."),
"16.4": ("Cái lạnh khắc nghiệt ở Greenland", "Và cái lạnh thật khắc nghiệt. Ở bắc Greenland, nhiệt độ có thể xuống khoảng âm 70 độ C."),
"16.5": ("Dải băng Nam Cực", "Ở đầu kia Trái Đất, châu Nam Cực nằm dưới dải băng lớn nhất hành tinh, chứa khoảng 70 phần trăm lượng nước ngọt của Trái Đất."),
"16.6": ("Sự sống và thềm băng Nam Cực", "Biển ở đây đầy chim cánh cụt, hải cẩu và cá voi, tất cả đều sống nhờ loài nhuyễn thể krill nhỏ bé. Vào mùa đông, thềm băng lan rộng, và những núi băng khổng lồ vỡ ra."),
"16.7": ("Trạm Vostok và hang băng", "Tại trạm Vostok ở Nam Cực, các nhà khoa học đã ghi nhận nhiệt độ thấp nhất từng đo được: âm 89,2 độ C."),
# 17
"17.1": ("Thế nào là sa mạc", "Sa mạc là những nơi khô hạn nhất Trái Đất, với ngày nóng như thiêu, đêm lạnh cóng, và có khi nhiều năm không một giọt mưa."),
"17.2": ("Sa mạc Sahara", "Sahara rộng gần bằng nước Mỹ, và vẫn đang lan rộng. Những đụn cát của nó cao tới 300 mét, và những cột xoáy bụi quay cuồng trên cát."),
"17.3": ("Bão cát haboob", "Ở Sudan, một bức tường bụi gọi là haboob có thể nuốt chửng cả một khu chợ chỉ trong vài phút, biến ban ngày thành bóng tối màu cam."),
"17.4": ("Nơi nóng nhất Trái Đất", "Nơi nóng nhất Trái Đất được công nhận là Thung lũng Chết ở California, từng đạt 56,7 độ C vào năm 1913, sau khi một kỷ lục cũ ở Libya bị bác bỏ."),
"17.5": ("Những nơi khô nhất", "Còn nơi khô nhất? Ở sa mạc Atacama, Chile, thị trấn Arica từng nhận chưa đến một mi-li-mét mưa trong suốt 59 năm."),
"17.6": ("Thành phố giữa sa mạc", "Vậy mà Las Vegas vẫn rực rỡ giữa sa mạc Mojave, sống nhờ nước sông Colorado, và các nhà khoa học cảnh báo một ngày nào đó vòi nước có thể cạn khô."),
"17.7": ("Cháy rừng", "Ở vùng đất khô hạn, lửa không bao giờ ở xa. Sét hoặc con người làm bùng lên những đám cháy, lan qua bụi rậm với tốc độ đáng sợ."),
"17.8": ("Kết: hành tinh không ngừng chuyển động", "Từ những quả cầu lửa trên bầu trời đến bóng tối nơi đáy đại dương sâu nhất, hành tinh của chúng ta đang sôi sục, rung chuyển, đóng băng và đổi thay mỗi ngày. Cảm ơn bạn đã theo dõi, và hãy đăng ký kênh để khám phá thêm những kỳ quan của thế giới."),
}
